//! Safety P32: risk-tier and interlock evidence qualification.
//! This surface emits a preflight receipt; it never claims to execute an interlock or instrument.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.safety.control-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct SafetyControl4{pub control_id:String,pub threat_class:String,pub mitigation_status:String,pub interlock_order:Vec<String>,pub signer:String,pub evidence_digest:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct SafetyIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub controls:Vec<SafetyControl4>,pub required_control_order:Vec<String>,pub required_interlock_order:Vec<String>,pub autonomy_tier:String,pub physical_effect:bool,pub signed_preflight:bool,pub human_authorized:bool,pub dry_run:bool,pub policy_allowed:bool,pub protected_closure:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:String,pub adversarial_events:Vec<String>,pub control_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct SafetyIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct SafetyIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub control_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub threat_order:Vec<String>,pub interlock_order:Vec<String>,pub signer_order:Vec<String>,pub autonomy_tier:String,pub physical_effect:bool,pub dry_run:bool,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:SafetyIntegrityArtifact4}
#[derive(Debug,Error)] pub enum SafetyIntegrityError{#[error("safety integrity input is invalid: {0}")] Invalid(String),#[error("safety integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())} fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])} fn invalid(v:impl Into<String>)->SafetyIntegrityError{SafetyIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"safety","consumers":["instrument gateway","autonomy broker","red-team auditor","research workbench"],"behavior":format!("qualify risk-tier interlock evidence at {scale} ({mode})"),"value":"prevents unverified physical or autonomous effects from being represented as safe","input_schema":"SafetyIntegrityRequest4@1","output_schema":"SafetyIntegrityCard7@1","effects":["emit:preflight-card","retain:threat-witness","block:unsafe-effect"],"permissions":["read:local-safety-evidence"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&SafetyIntegrityCard7)->Result<(),SafetyIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("safety identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.control_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.threat_order,&c.interlock_order,&c.signer_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("safety vectors are not canonical"));}}let ids=c.control_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("control states do not partition controls"));}Ok(())}
pub fn qualify(q:&SafetyIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<SafetyIntegrityCard7,SafetyIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.controls.is_empty()||q.required_control_order.is_empty()||!canonical(&q.required_control_order)||!canonical(&q.required_interlock_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.control_budget==0{return Err(invalid("safety identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.controls.clone();rows.sort_by(|a,b|a.control_id.cmp(&b.control_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut threats=BTreeSet::new();let mut interlocks=BTreeSet::new();let mut signers=BTreeSet::new();let mut evidence=BTreeSet::new();for c in &rows{if c.control_id.trim().is_empty()||!seen.insert(c.control_id.clone())||c.threat_class.trim().is_empty()||c.mitigation_status.trim().is_empty()||c.signer.trim().is_empty()||!digest(&c.evidence_digest)||!c.local||!c.aggregate_only{return Err(invalid("control identity, mitigation, signer, evidence, or locality is invalid"));}threats.insert(format!("{}:{}",c.control_id,c.threat_class));interlocks.extend(c.interlock_order.iter().map(|x|format!("{}:{}",c.control_id,x)));signers.insert(format!("{}:{}",c.control_id,c.signer));evidence.insert(c.evidence_digest.clone());if c.evidence_digest==q.replay_identity||c.mitigation_status=="unknown"{unknown.insert(c.control_id.clone());}else if c.mitigation_status!="enforced"||c.interlock_order!=q.required_interlock_order||c.signer=="unverified"{rejected.insert(c.control_id.clone());}else if !q.required_control_order.contains(&c.control_id){omitted.insert(c.control_id.clone());}else{accepted.insert(c.control_id.clone());}}let missing=q.required_control_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.raw_data_local||!q.aggregate_only||!q.signed_preflight||(q.physical_effect&&!q.human_authorized)||!q.adversarial_events.is_empty()||rows.len()>q.control_budget||(!q.dry_run&&q.autonomy_tier=="A0");if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let complete=missing.is_empty();let disposition=if global{"blocked"}else if !complete||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let control_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"control_order":control_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"threat_order":threats.into_iter().collect::<Vec<_>>(),"interlock_order":interlocks.into_iter().collect::<Vec<_>>(),"signer_order":signers.into_iter().collect::<Vec<_>>(),"autonomy_tier":q.autonomy_tier,"physical_effect":q.physical_effect,"dry_run":q.dry_run,"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|SafetyIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:safety-preflight:{}",q.request_id)]}else{vec!["block:unsafe-effect".into()]};let artifact=SafetyIntegrityArtifact4{artifact_id:format!("safety-control:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=SafetyIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),control_order:body["control_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,threat_order:body["threat_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),interlock_order:body["interlock_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),signer_order:body["signer_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),autonomy_tier:q.autonomy_tier.clone(),physical_effect:q.physical_effect,dry_run:q.dry_run,replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
